// Writes content/units/y12-economics-essay-writing/answers.ts from the reviewed essay content (spec 010 T080,
// content-prompt.md). Inputs stay in gitignored resources/; only the generated file is committed.
//
//   npm run essay-build-answers                 (writes the file for every approved essay)
//   npm run essay-build-answers -- --dry-run    (prints what it would write, changes nothing)
//
// Inputs:
//   resources/topic011/content/<id>.json   one per essay, id e1 to e6:
//     { "schoolCriteria": string | null, "markingNotes": string, "modelEssay": string, "concepts": ["china-wto", ...] }
//     `concepts` are keys of lib/essay/concepts.json (this script turns them into full concept ids).
//   resources/topic011/review/approved.json   ["e1", "e3", ...]: the essays the user has approved in the review report.
//
// It refuses a model essay outside 600 to 800 words, a concept key that is not on the list and a trial essay with no
// school criteria. It never sets `live`: that is a one-line change in questions.ts, made only after the marker check.

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import concepts from "../lib/essay/concepts.json";
import { ESSAY_MAX, ESSAY_MIN } from "../lib/essay/counter";
import { countWords } from "../lib/wordcount";

const UNIT = "y12-economics-essay-writing";
const ROOT = process.cwd();
const CONTENT = join(ROOT, "resources", "topic011", "content");
const APPROVED = join(ROOT, "resources", "topic011", "review", "approved.json");
const OUT = join(ROOT, "content", "units", UNIT, "answers.ts");
const TRIAL = new Set(["e1", "e3", "e4"]);
const DRY = process.argv.includes("--dry-run");

interface Input {
  schoolCriteria: string | null;
  markingNotes: string;
  modelEssay: string;
  concepts: string[];
}

function fail(message: string): never {
  console.error(`✗ ${message}`);
  process.exit(1);
}

if (!existsSync(APPROVED)) fail(`No ${APPROVED}: nothing has been approved yet.`);
const approved = JSON.parse(readFileSync(APPROVED, "utf8")) as string[];
if (!Array.isArray(approved) || approved.some((id) => !/^e[1-6]$/.test(id))) fail("approved.json must be a list of essay ids e1 to e6.");

const entries: string[] = [];
for (const id of [...new Set(approved)].sort()) {
  const file = join(CONTENT, `${id}.json`);
  if (!existsSync(file)) fail(`${id} is approved but ${file} does not exist.`);
  const e = JSON.parse(readFileSync(file, "utf8")) as Input;
  if (!e.markingNotes?.trim()) fail(`${id}: markingNotes is empty.`);
  const words = countWords(e.modelEssay ?? "");
  if (words < ESSAY_MIN || words > ESSAY_MAX) fail(`${id}: the model essay is ${words} words; it must be ${ESSAY_MIN} to ${ESSAY_MAX}.`);
  if (!Array.isArray(e.concepts) || e.concepts.length === 0) fail(`${id}: no concept keys.`);
  for (const k of e.concepts) if (!(k in concepts)) fail(`${id}: concept key "${k}" is not in lib/essay/concepts.json.`);
  const criteria = e.schoolCriteria && e.schoolCriteria.trim() ? e.schoolCriteria : null;
  if (TRIAL.has(id) && !criteria) fail(`${id}: a school-trial essay needs the school's criteria (schoolCriteria).`);
  if (!TRIAL.has(id) && criteria) fail(`${id}: an original essay has no school criteria (schoolCriteria must be null).`);
  entries.push(
    `  [\`\${UNIT}.${id}\`]: {\n    rubric: [],\n    essay: {\n      markingNotes: ${JSON.stringify(e.markingNotes)},\n      schoolCriteria: ${JSON.stringify(criteria)},\n      modelEssay: ${JSON.stringify(e.modelEssay)},\n      concepts: ${JSON.stringify(e.concepts.map((k) => `${UNIT}.c-${k}`))},\n    },\n  },`,
  );
  console.log(`${id}: ${words} words, ${e.concepts.length} concept tag(s), ${criteria ? "school criteria" : "no school criteria"}`);
}

const file = `import type { AnswerSet } from "@/lib/types";

// SERVER ONLY — the essays' keys (constitution Principle I): the marking notes, the school's own criteria (trial
// essays), the band 1 model essay and the concept tags. GENERATED by \`npm run essay-build-answers\` from the reviewed
// content in resources/topic011/content/; do not edit by hand. An essay without a key stays \`live: false\`.

const UNIT = "${UNIT}";

export const answers: AnswerSet = {
${entries.join("\n")}
};
`;

if (DRY) {
  console.log(`\n(dry run) would write ${entries.length} essay key(s) to ${OUT}`);
} else {
  writeFileSync(OUT, file, "utf8");
  console.log(`\n✓ Wrote ${entries.length} essay key(s) to content/units/${UNIT}/answers.ts. Next: set live: true in questions.ts for each one the marker check has passed, then run the full chain.`);
}
